1	package clinical
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Grant 由内部使用者为一名接收方建立针对某患者的整类读取授权。
11	//
12	// 这是 [Store.GrantSelective] 的整类形式：范围由明确的“就诊 + 类别
13	// （诊断/医嘱）”组合构成，覆盖各就诊+类别下的全部已生效记录（含授权
14	// 建立后才生效的记录）。不允许空范围，每个就诊都必须属于该患者
15	// （跨患者就诊会被拒绝），类别必须合法。时间窗为半开区间
16	// [startsAt, expiresAt)：开始时刻即生效，到截止时刻立即失效；
17	// 开始不早于截止时间（相等也算）一律拒绝。患者档案停用后不能新建授权。
18	// 授权与审计事件在同一次原子落盘中保留。
19	func (s *Store) Grant(actor Actor, patientID ID, receiverID string, scopes []Scope, startsAt, expiresAt time.Time) (Authorization, error) {
20		return s.GrantSelective(actor, patientID, receiverID, scopes, nil, startsAt, expiresAt)
21	}
22	
23	// GrantSelective 由内部使用者为一名接收方建立针对某患者的读取授权，
24	// 整类范围（scopes）与限定记录范围（selections）可以并存，同一条授权
25	// 可以包含多个就诊、类别。
26	//
27	// scopes 的每项按整类授权：覆盖该就诊+类别下全部已生效记录，并自然
28	// 包含授权后新增生效的记录；selections 的每项明确选出一条已生效记录，
29	// 被选记录更正后授权覆盖它的当前版本，但同一就诊同一类别的其他记录、
30	// 后来新增并生效的记录都不会自动进入限定范围。重复选择同一记录只算一次。
31	//
32	// scopes 与 selections 不能同时为空：空选择不代表整类授权。scope 中的
33	// 就诊必须存在且属于该患者，类别必须合法。每条 selection 都必须显式
34	// 声明记录所属的就诊与类别，且：记录不存在返回 ErrNotFound；记录属于
35	// 其他患者返回 ErrMismatchedPatient；空选择、空白标识、选择了尚未生效
36	// 的草稿、记录与声明的就诊或类别不符返回 ErrInvalidArgument。任一选择
37	// 不合法就拒绝整条授权：不保存合法部分，也不新增审计。
38	//
39	// 时间窗、停用档案与审计规则与 [Store.Grant] 相同。
40	func (s *Store) GrantSelective(actor Actor, patientID ID, receiverID string, scopes []Scope, selections []RecordSelection, startsAt, expiresAt time.Time) (Authorization, error) {
41		if !actor.valid() || !actor.IsInternal() {
42			return Authorization{}, ErrAccessDenied
43		}
44		if patientID == "" {
45			return Authorization{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
46		}
47		if strings.TrimSpace(receiverID) == "" {
48			return Authorization{}, fmt.Errorf("%w: receiver id is required", ErrInvalidArgument)
49		}
50		if len(scopes) == 0 && len(selections) == 0 {
51			return Authorization{}, fmt.Errorf("%w: authorization scope must not be empty", ErrInvalidArgument)
52		}
53		for _, sc := range scopes {
54			if sc.EncounterID == "" {
55				return Authorization{}, fmt.Errorf("%w: scope encounter id is required", ErrInvalidArgument)
56			}
57			if !validCategory(sc.Category) {
58				return Authorization{}, fmt.Errorf("%w: scope category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
59			}
60		}
61		for _, sel := range selections {
62			if strings.TrimSpace(sel.RecordID) == "" {
63				return Authorization{}, fmt.Errorf("%w: selection record id is required", ErrInvalidArgument)
64			}
65			if strings.TrimSpace(sel.EncounterID) == "" {
66				return Authorization{}, fmt.Errorf("%w: selection encounter id is required", ErrInvalidArgument)
67			}
68			if !validCategory(sel.Category) {
69				return Authorization{}, fmt.Errorf("%w: selection category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
70			}
71		}
72		if !startsAt.Before(expiresAt) {
73			return Authorization{}, fmt.Errorf("%w: starts-at must be strictly before expires-at", ErrInvalidArgument)
74		}
75	
76		var result Authorization
77		err := s.mutate(func(snap *snapshot) error {
78			if _, err := requireActivePatient(snap, patientID); err != nil {
79				return err
80			}
81	
82			// 去重并逐项校验整类范围：引用的就诊必须存在且属于该患者。
83			seenScope := map[Scope]bool{}
84			cleanedScopes := make([]Scope, 0, len(scopes))
85			for _, sc := range scopes {
86				if _, err := requireEncounter(snap, patientID, sc.EncounterID); err != nil {
87					return err
88				}
89				if seenScope[sc] {
90					continue
91				}
92				seenScope[sc] = true
93				cleanedScopes = append(cleanedScopes, sc)
94			}
95			sort.Slice(cleanedScopes, func(i, j int) bool {
96				if cleanedScopes[i].EncounterID != cleanedScopes[j].EncounterID {
97					return cleanedScopes[i].EncounterID < cleanedScopes[j].EncounterID
98				}
99				return cleanedScopes[i].Category < cleanedScopes[j].Category
100			})
101	
102			// 逐项校验限定范围：就诊必须属于该患者；记录必须存在、属于该患者、
103			// 已生效，且实际就诊与类别与声明一致。任一不合法即整体拒绝。
104			seenRecord := map[ID]bool{}
105			cleanedSelections := make([]RecordSelection, 0, len(selections))
106			for _, sel := range selections {
107				if _, err := requireEncounter(snap, patientID, sel.EncounterID); err != nil {
108					return err
109				}
110				r := snap.Records[sel.RecordID]
111				if r == nil {
112					return fmt.Errorf("%w: record %q", ErrNotFound, sel.RecordID)
113				}
114				if r.PatientID != patientID {
115					return fmt.Errorf("%w: record %q belongs to patient %q, not %q",
116						ErrMismatchedPatient, sel.RecordID, r.PatientID, patientID)
117				}
118				if r.CurrentVersionID == "" {
119					return fmt.Errorf("%w: record %q has no effective version; activate its draft first",
120						ErrInvalidArgument, sel.RecordID)
121				}
122				if r.EncounterID != sel.EncounterID || r.Category != sel.Category {
123					return fmt.Errorf("%w: record %q belongs to encounter %q category %q, not declared encounter %q category %q",
124						ErrInvalidArgument, sel.RecordID, r.EncounterID, r.Category, sel.EncounterID, sel.Category)
125				}
126				if seenRecord[sel.RecordID] {
127					// 重复选择同一记录只算一次。
128					continue
129				}
130				seenRecord[sel.RecordID] = true
131				cleanedSelections = append(cleanedSelections, sel)
132			}
133			sort.Slice(cleanedSelections, func(i, j int) bool {
134				return cleanedSelections[i].RecordID < cleanedSelections[j].RecordID
135			})
136	
137			now := s.now()
138			a := &Authorization{
139				ID:         newID("auth"),
140				PatientID:  patientID,
141				ReceiverID: receiverID,
142				Scopes:     cleanedScopes,
143				Selections: cleanedSelections,
144				StartsAt:   startsAt.UTC(),
145				ExpiresAt:  expiresAt.UTC(),
146				CreatedAt:  now,
147			}
148			snap.Authorizations[a.ID] = a
149			s.addAudit(snap, patientID, actor, ActionGranted, "authorization", a.ID, now)
150			result = cloneAuthorizationValue(a)
151			return nil
152		})
153		return result, err
154	}
155	
156	// Revoke 提前撤回授权。撤回在当前时间生效；此后该授权不再覆盖任何读取。
157	// 重复撤回返回成功且不产生额外变化（不新增审计事件），与“停用”语义一致。
158	// 撤回其他患者的授权 ID 会得到 ErrMismatchedPatient/ErrNotFound。
159	func (s *Store) Revoke(actor Actor, patientID, authorizationID ID) error {
160		if !actor.valid() || !actor.IsInternal() {
161			return ErrAccessDenied
162		}
163		return s.mutate(func(snap *snapshot) error {
164			a := snap.Authorizations[authorizationID]
165			if a == nil {
166				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
167			}
168			if a.PatientID != patientID {
169				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
170					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
171			}
172			if a.RevokedAt != nil {
173				// 幂等：保持已有撤回结果，不生成额外变化或事件。
174				return nil
175			}
176			now := s.now()
177			a.RevokedAt = &now
178			s.addAudit(snap, patientID, actor, ActionRevoked, "authorization", a.ID, now)
179			return nil
180		})
181	}
182	
183	// GetAuthorization 返回单个授权。仅供内部使用者。
184	func (s *Store) GetAuthorization(actor Actor, patientID, authorizationID ID) (Authorization, error) {
185		if !actor.valid() || !actor.IsInternal() {
186			return Authorization{}, ErrAccessDenied
187		}
188		var result Authorization
189		err := s.view(func(snap *snapshot) error {
190			a := snap.Authorizations[authorizationID]
191			if a == nil {
192				return fmt.Errorf("%w: authorization %q", ErrNotFound, authorizationID)
193			}
194			if a.PatientID != patientID {
195				return fmt.Errorf("%w: authorization %q belongs to patient %q, not %q",
196					ErrMismatchedPatient, authorizationID, a.PatientID, patientID)
197			}
198			result = cloneAuthorizationValue(a)
199			return nil
200		})
201		return result, err
202	}
203	
204	// ListAuthorizations 列出某患者（可选：某接收方）的全部授权，含已撤回者。
205	// 仅供内部使用者。
206	func (s *Store) ListAuthorizations(actor Actor, patientID ID, receiverID string) ([]Authorization, error) {
207		if !actor.valid() || !actor.IsInternal() {
208			return nil, ErrAccessDenied
209		}
210		var result []Authorization
211		err := s.view(func(snap *snapshot) error {
212			if _, err := requirePatient(snap, patientID); err != nil {
213				return err
214			}
215			for _, a := range snap.Authorizations {
216				if a.PatientID != patientID {
217					continue
218				}
219				if receiverID != "" && a.ReceiverID != receiverID {
220					continue
221				}
222				result = append(result, cloneAuthorizationValue(a))
223			}
224			sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
225			return nil
226		})
227		return result, err
228	}
229	
230	// Read 供接收方按自己的身份读取某次就诊下某个类别（诊断/医嘱）的内容。
231	//
232	// 结果是该接收方在“本次读取时间”所有当前有效授权允许记录的合集。“本次读取
233	// 时间”指真正开始核对权限的时刻：请求发出后若因等待同一存储上的其他操作而
234	// 排队，以等待结束、开始核对时的同一时刻统一判断本次涉及的各条授权是否有效，
235	// 等待本身不会延长或推迟授权的有效期。每条记录
236	// 只出现一次并按记录标识稳定排序：授权必须属于该接收方与该患者、已开始、
237	// 未到期且未撤回；整类范围（Scope）允许该就诊+类别下的全部已生效记录
238	// （含授权后才生效者），限定范围（RecordSelection）仅允许明确选中的记录。
239	// 同一条记录被多条授权（含整类与限定重叠）允许也只出现一次；被选记录被
240	// 更正后读取其当前生效版本。看不到草稿、旧版本或更正原因。
241	//
242	// 若不存在任何覆盖所请求就诊+类别的有效授权（全部尚未开始、已到期或已
243	// 撤回），或患者档案已停用，返回 ErrAccessDenied：结果中不含任何未授权
244	// 记录的标识、数量或内容。撤回整类授权后，只剩其他有效授权明确允许的记录。
245	func (s *Store) Read(actor Actor, patientID, encounterID ID, category string) (ReadResult, error) {
246		if !actor.valid() || actor.Kind != "receiver" {
247			return ReadResult{}, ErrAccessDenied
248		}
249		if patientID == "" || encounterID == "" {
250			return ReadResult{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
251		}
252		if !validCategory(category) {
253			return ReadResult{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
254		}
255	
256		var out ReadResult
257		err := s.view(func(snap *snapshot) error {
258			// 查阅时刻在进入临界区、真正开始核对权限时才取样：请求发出后若因
259			// 等待其他操作而排队，等待时间不能延长或推迟授权的有效判断——
260			// 本次读取涉及的所有授权统一按这同一时刻判断是否有效。
261			now := s.now()
262			// 汇总当前有效的授权：哪些整类（就诊+类别）被覆盖，哪些具体记录被
263			// 限定范围明确允许。不提前区分“对象不存在/属于他人”与“无授权”，
264			// 统一返回拒绝，从而不向接收方泄露患者或就诊是否存在。
265			wholeCategory := false
266			allowedRecords := map[ID]bool{}
267			patientDeactivated := false
268			if p := snap.Patients[patientID]; p != nil {
269				patientDeactivated = p.Deactivated
270			}
271			for _, a := range snap.Authorizations {
272				if a.PatientID != patientID || a.ReceiverID != actor.ID {
273					continue
274				}
275				if !a.ActiveAt(now) {
276					continue
277				}
278				if authorizationCovers(a, encounterID, category) {
279					wholeCategory = true
280				}
281				for _, sel := range a.Selections {
282					if sel.EncounterID == encounterID && sel.Category == category {
283						allowedRecords[sel.RecordID] = true
284					}
285				}
286			}
287			if patientDeactivated || (!wholeCategory && len(allowedRecords) == 0) {
288				// 无授权、未开始、已到期、已撤回或档案停用：明确拒绝，
289				// 结果中不含任何受保护内容。
290				return ErrAccessDenied
291			}
292	
293			// 能被授权覆盖的就诊必然属于该患者（Grant 时已校验），
294			// 此处再确认一次以防任何不一致状态。
295			e := snap.Encounters[encounterID]
296			if e == nil || e.PatientID != patientID {
297				return ErrAccessDenied
298			}
299	
300			out.EncounterID = encounterID
301			out.Category = category
302			var recs []EffectiveRecord
303			for _, r := range snap.Records {
304				if r.EncounterID != encounterID || r.Category != category || r.PatientID != patientID {
305					continue
306				}
307				// 整类范围覆盖全部；限定范围只覆盖明确选中的记录。
308				// 多个授权、整类与限定重叠时同一条记录只出现一次。
309				if !wholeCategory && !allowedRecords[r.ID] {
310					continue
311				}
312				if eff, ok := currentEffective(snap, r); ok {
313					recs = append(recs, eff)
314				}
315				// 仅有草稿、尚无生效版本的记录天然不出现；
316				// 限定授权选中的记录在授权后也不会退回草稿状态。
317			}
318			sort.Slice(recs, func(i, j int) bool { return recs[i].RecordID < recs[j].RecordID })
319			out.Records = recs
320			return nil
321		})
322		return out, err
323	}
324	
325	// cloneAuthorizationValue 返回授权的深拷贝：整类范围、限定范围与撤回时间
326	// 都与库内保存的对象各自独立。返回给调用方的授权只是本次操作得到的信息；
327	// 调用方在本地修改它（改范围、换记录标识、改撤回时间）不能改变库内正式
328	// 保存的授权，从同一授权取得的多份结果也互不影响。
329	func cloneAuthorizationValue(a *Authorization) Authorization {
330		out := *a
331		out.Scopes = append([]Scope(nil), a.Scopes...)
332		out.Selections = append([]RecordSelection(nil), a.Selections...)
333		if a.RevokedAt != nil {
334			t := *a.RevokedAt
335			out.RevokedAt = &t
336		}
337		return out
338	}
339	
340	// authorizationCovers 报告授权的整类范围是否覆盖某次就诊下某个类别。
341	func authorizationCovers(a *Authorization, encounterID ID, category string) bool {
342		for _, sc := range a.Scopes {
343			if sc.EncounterID == encounterID && sc.Category == category {
344				return true
345			}
346		}
347		return false
348	}
349	
350	// authorizationCoversRecord 报告授权本身（整类范围或限定范围）是否覆盖
351	// 某条具体记录：整类范围按记录的就诊+类别覆盖，限定范围只覆盖明确选中
352	// 的记录。其他授权不能替代该绑定授权完成覆盖。
353	func authorizationCoversRecord(a *Authorization, r *Record) bool {
354		if authorizationCovers(a, r.EncounterID, r.Category) {
355			return true
356		}
357		for _, sel := range a.Selections {
358			if sel.RecordID == r.ID {
359				return true
360			}
361		}
362		return false
363	}
364

