747			t.Fatalf("retry after reopen = %+v", retry)
748		}
749		if retry.Package.Records[0].Content != "包内v1" {
750			t.Fatalf("retry refetched current content: %+v", retry.Package.Records)
751		}
752		if n := len(mustAudit(t, s2, p.ID)); n != auditBefore {
753			t.Fatalf("retry after reopen added audit: %d", n)
754		}
755	
756		// 审计两类事件都在。
757		var creates, receipts int
758		for _, ev := range mustAudit(t, s2, p.ID) {
759			switch ev.Action {
760			case ActionExchanged:
761				creates++
762			case ActionReceipted:
763				receipts++
764			}
765		}
766		if creates != 1 || receipts != 1 {
767			t.Fatalf("audit after reopen: creates=%d receipts=%d", creates, receipts)
768		}
769	
770		// 取包路径在重开后同样按当前时间与绑定授权判断（窗口内可取）。
771		del, err := s2.FetchPackage(rcv, x.ID)
772		if err != nil {
773			t.Fatalf("fetch after reopen: %v", err)
774		}
775		if del.Digest != x.Digest || del.Status != ExchangeRejected {
776			t.Fatalf("delivery after reopen wrong: %+v", del)
777		}
778	}
779	
780	// 关闭后调用返回 ErrClosed。
781	func TestExchangeOperationsAfterClose(t *testing.T) {
782		f := setupExchange(t)
783		x, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed")
784		if err != nil {
785			t.Fatal(err)
786		}
787		if err := f.s.Close(); err != nil {
788			t.Fatal(err)
789		}
790		if _, err := f.s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.diag}, "req-closed-2"); !errors.Is(err, ErrClosed) {
791			t.Fatalf("create after close err = %v", err)
792		}
793		if _, err := f.s.FetchPackage(rcv, x.ID); !errors.Is(err, ErrClosed) {
794			t.Fatalf("fetch after close err = %v", err)
795		}
796		if _, err := f.s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, ""); !errors.Is(err, ErrClosed) {
797			t.Fatalf("receipt after close err = %v", err)
798		}
799		if _, err := f.s.GetExchange(doc, f.pid, x.ID); !errors.Is(err, ErrClosed) {
800			t.Fatalf("get after close err = %v", err)
801		}
802	}
