554		}
555		if g2.Status != ExchangePending || g2.Receipt != nil {
556			t.Fatalf("fabricated receipt leaked into store: %+v", g2)
557		}
558	
559		// 列表结果中补造假回执同样无效。
560		lst, err := f.s.ListExchanges(doc, f.pid)
561		if err != nil {
562			t.Fatal(err)
563		}
564		if len(lst) != 1 || lst[0].Receipt != nil || lst[0].Status != ExchangePending {
565			t.Fatalf("list reflects fabricated receipt: %+v", lst)
566		}
567		lst[0].Status = ExchangeAccepted
568		lst[0].Receipt = &Receipt{Outcome: ReceiptAccepted, RegisteredAt: time.Now()}
569	
570		g3, _ := f.s.GetExchange(doc, f.pid, x.ID)
571		if g3.Status != ExchangePending || g3.Receipt != nil {
572			t.Fatalf("fabricated receipt via list leaked into store: %+v", g3)
573		}
574	
575		// 接收方取包看到的仍是待回执。
576		d, err := f.s.FetchPackage(rcv, x.ID)
577		if err != nil {
578			t.Fatal(err)
579		}
580		if d.Status != ExchangePending {
581			t.Fatalf("delivery status = %q, want %q", d.Status, ExchangePending)
582		}
583	
584		// 自始至终没有任何回执审计。
585		if c := receiptAuditCount(t, f.s, f.pid); c != 0 {
586			t.Fatalf("receipt audits = %d, want 0", c)
587		}
