	assertExchangeMatches(t, g2, want, "previously fetched copy after another copy tampered")

	// 库内交换不变。
	g3, err := f.s.GetExchange(doc, f.pid, created.ID)
	if err != nil {
		t.Fatal(err)
	}
	assertExchangeMatches(t, g3, want, "fresh GetExchange after tampering a copy")

