143	// ---- 同进程内：第二次打开立即失败、返回空句柄，且不影响原使用者 ----
144	
145	func TestSecondOpenSameProcessRejectedAndHolderUnaffected(t *testing.T) {
146		dir := t.TempDir()
147		s1, err := Open(dir)
148		if err != nil {
149			t.Fatalf("first open: %v", err)
150		}
151		t.Cleanup(func() { _ = s1.Close() })
152	
153		reject := func(label string) {
154			t.Helper()
155			s2, err := Open(dir)
156			if err == nil {
157				_ = s2.Close()
158				t.Fatalf("%s: second Open must fail", label)
159			}
160			if s2 != nil {
161				t.Fatalf("%s: rejected Open must return nil handle, got %#v", label, s2)
162			}
163			if !strings.Contains(err.Error(), alreadyInUseMsg) {
164				t.Fatalf("%s: error does not say directory is in use: %v", label, err)
165			}
166		}
167	
168		reject("first rejection")
169	
170		// 原 Store 继续登记患者、管理记录，且数据真正落盘。
171		p, err := s1.RegisterPatient(doc, "锁互斥患者")
172		if err != nil {
173			t.Fatalf("register after rejected open: %v", err)
174		}
175		enc, err := s1.AddEncounter(doc, p.ID, time.Time{})
176		if err != nil {
177			t.Fatalf("add encounter after rejected open: %v", err)
178		}
179		draft, err := s1.CreateDraft(doc, p.ID, enc.ID, Diagnosis, "初版诊断")
180		if err != nil {
181			t.Fatalf("create draft after rejected open: %v", err)
182		}
183		v1, err := s1.ActivateRecord(doc, draft.ID)
184		if err != nil {
185			t.Fatalf("activate after rejected open: %v", err)
186		}
187		v2, err := s1.CorrectRecord(doc, draft.ID, v1.Number, "复核后的诊断", "复核补录")
188		if err != nil {
189			t.Fatalf("correct after rejected open: %v", err)
190		}
191	
192		// 被拒绝的调用不能改变占用状态：第三次打开仍应立即失败。
193		reject("second rejection")
194	
195		// 查询历史、版本链与审计在原 Store 上完整可用。
196		hist, err := s1.EncounterRecords(doc, p.ID, enc.ID)
197		if err != nil {
198			t.Fatalf("query history: %v", err)
199		}
200		if len(hist) != 1 {
201			t.Fatalf("history len = %d, want 1", len(hist))
202		}
203		rh := hist[0]
204		if rh.CurrentVersion == nil || rh.CurrentVersion.ID != v2.ID || len(rh.Versions) != 2 {
205			t.Fatalf("version chain broken after rejected open: %+v", rh)
206		}
207		acts := auditActions(mustAudit(t, s1, p.ID))
208		if acts[ActionActivated] != 1 || acts[ActionCorrected] != 1 {
209			t.Fatalf("audit events changed by rejected open: %+v", acts)
210		}
211	
212		// 关闭后再开，已提交的患者、版本与审计原样保留。
213		if err := s1.Close(); err != nil {
214			t.Fatal(err)
215		}
216		s3, err := Open(dir)
217		if err != nil {
218			t.Fatalf("reopen after close: %v", err)
219		}
220		t.Cleanup(func() { _ = s3.Close() })
221		got, err := s3.GetPatient(doc, p.ID)
222		if err != nil {
223			t.Fatalf("patient lost across reopen: %v", err)
224		}
225		if got.Name != "锁互斥患者" || got.Source != SyntheticSource {
226			t.Fatalf("patient content changed across reopen: %+v", got)
227		}
228		reopened, err := s3.EncounterRecords(doc, p.ID, enc.ID)
229		if err != nil {
230			t.Fatalf("history after reopen: %v", err)
231		}
232		if len(reopened) != 1 || reopened[0].CurrentVersion == nil ||
233			reopened[0].CurrentVersion.ID != v2.ID || len(reopened[0].Versions) != 2 {
234			t.Fatalf("version history not preserved across reopen: %+v", reopened)
235		}
236		acts2 := auditActions(mustAudit(t, s3, p.ID))
237		if acts2[ActionActivated] != 1 || acts2[ActionCorrected] != 1 {
238			t.Fatalf("audit not preserved across reopen: %+v", acts2)
239		}
240	}
