242	// ---- 跨进程：另一个独立进程持有时，Open 必须立即失败而非等待其关闭 ----
243	
244	func TestOpenRejectedByIndependentProcess(t *testing.T) {
245		dir := t.TempDir()
246	
247		// 先由本进程写入一批已提交数据，再交给独立进程重新打开持有。
248		s0, err := Open(dir)
249		if err != nil {
250			t.Fatalf("seed open: %v", err)
251		}
252		p, err := s0.RegisterPatient(doc, "跨进程患者")
253		if err != nil {
254			t.Fatal(err)
255		}
256		enc, err := s0.AddEncounter(doc, p.ID, time.Time{})
257		if err != nil {
258			t.Fatal(err)
259		}
260		draft, err := s0.CreateDraft(doc, p.ID, enc.ID, Order, "跨进程医嘱")
261		if err != nil {
262			t.Fatal(err)
263		}
264		if _, err := s0.ActivateRecord(doc, draft.ID); err != nil {
265			t.Fatal(err)
266		}
267		if err := s0.Close(); err != nil {
268			t.Fatal(err)
269		}
270	
271		h := spawnHolder(t, dir)
272		if line := h.waitReady(t); line != "READY" {
273			t.Fatalf("holder did not open directory, reported: %q", line)
274		}
275	
276		// 子进程持有期间：Open 必须立即失败（子进程只有在本测试后面的
277		// release 时才会关闭），错误明确说明目录正在使用，句柄为空。
278		start := time.Now()
279		s1, err := Open(dir)
280		waited := time.Since(start)
281		if err == nil {
282			_ = s1.Close()
283			t.Fatal("Open against directory held by another process must fail")
284		}
285		if s1 != nil {
286			t.Fatalf("rejected cross-process Open must return nil handle, got %#v", s1)
287		}
288		if !strings.Contains(err.Error(), alreadyInUseMsg) {
289			t.Fatalf("cross-process error does not say directory is in use: %v", err)
290		}
291		if waited > 5*time.Second {
292			t.Fatalf("Open waited %s for holder to close; must fail immediately", waited)
293		}
294	
295		// 再次尝试仍立即失败，证明被拒调用没有干扰任何一方的占用。
296		if _, err := Open(dir); err == nil || !strings.Contains(err.Error(), alreadyInUseMsg) {
297			t.Fatalf("second cross-process Open not rejected: %v", err)
298		}
299	
300		// 持有者关闭后，同一目录可正常重开，先前提交的数据完整保留。
301		h.release(t)
302		s2, err := Open(dir)
303		if err != nil {
304			t.Fatalf("reopen after holder exit: %v", err)
305		}
306		t.Cleanup(func() { _ = s2.Close() })
307		if got, err := s2.GetPatient(doc, p.ID); err != nil || got.Name != "跨进程患者" {
308			t.Fatalf("committed patient not preserved while another process held dir: %+v, %v", got, err)
309		}
310		hist, err := s2.EncounterRecords(doc, p.ID, enc.ID)
311		if err != nil {
312			t.Fatalf("history after holder exit: %v", err)
313		}
314		if len(hist) != 1 || hist[0].CurrentVersion == nil || len(hist[0].Versions) != 1 {
315			t.Fatalf("committed version history not preserved: %+v", hist)
316		}
317		if acts := auditActions(mustAudit(t, s2, p.ID)); acts[ActionActivated] != 1 {
318			t.Fatalf("committed audit not preserved: %+v", acts)
319		}
320	}
