368	// ---- 残留的锁标记文件不代表占用：无需手动删除即可重开 ----
369	
370	func TestStaleLockMarkerDoesNotBlockReopen(t *testing.T) {
371		dir := t.TempDir()
372		s1, err := Open(dir)
373		if err != nil {
374			t.Fatal(err)
375		}
376		p, err := s1.RegisterPatient(doc, "残留标记患者")
377		if err != nil {
378			t.Fatal(err)
379		}
380		if err := s1.Close(); err != nil {
381			t.Fatal(err)
382		}
383	
384		// 模拟上次使用（或异常退出）留下的占用标记文件：文件在，但没有任何
385		// 存活句柄持锁。单凭该文件不得判定目录仍被占用。
386		marker := filepath.Join(dir, ".clinical.lock")
387		if err := os.WriteFile(marker, []byte("stale marker from previous use\n"), 0o644); err != nil {
388			t.Fatalf("write stale marker: %v", err)
389		}
390	
391		s2, err := Open(dir)
392		if err != nil {
393			t.Fatalf("stale marker must not block reopen: %v", err)
394		}
395		t.Cleanup(func() { _ = s2.Close() })
396		if got, err := s2.GetPatient(doc, p.ID); err != nil || got.Name != "残留标记患者" {
397			t.Fatalf("data not readable over stale marker: %+v, %v", got, err)
398		}
399		if err := s2.Close(); err != nil {
400			t.Fatal(err)
401		}
402	
403		// 连续多轮开关都应正常，且锁标记再次残留也不影响。
404		for i := 0; i < 3; i++ {
405			s, err := Open(dir)
406			if err != nil {
407				t.Fatalf("reopen %d over residual marker failed: %v", i, err)
408			}
409			if err := s.Close(); err != nil {
410				t.Fatalf("close %d: %v", i, err)
411			}
412		}
413	}
