415	// ---- 打开失败时释放占用：数据损坏/格式不受支持后，修正数据可重开 ----
416	
417	func TestOpenFailureReleasesDirectory(t *testing.T) {
418		dir := t.TempDir()
419	
420		cases := []struct {
421			name    string
422			content []byte
423			setup   func(string) error
424		}{
425			{
426				name:    "unreadable-json",
427				content: []byte("{this is not valid json"),
428			},
429			{
430				name:    "unsupported-format-version",
431				content: []byte(fmt.Sprintf(`{"format_version":%d}`, dataVersion+99)),
432			},
433			{
434				name: "data-path-is-directory",
435				setup: func(dir string) error {
436					// 快照路径存在且是目录时无法作为文件读取。
437					return os.Mkdir(filepath.Join(dir, dataName), 0o755)
438				},
439			},
440		}
441		for _, tc := range cases {
442			t.Run(tc.name, func(t *testing.T) {
443				// 每个子场景从干净目录开始（锁标记文件残留无害，保留它还能
444				// 顺带验证残留标记不影响数据损坏时的失败路径）。
445				if err := os.RemoveAll(filepath.Join(dir, dataName)); err != nil {
446					t.Fatal(err)
447				}
448				if tc.setup != nil {
449					if err := tc.setup(dir); err != nil {
450						t.Fatal(err)
451					}
452				} else {
453					if err := os.WriteFile(filepath.Join(dir, dataName), tc.content, 0o600); err != nil {
454						t.Fatal(err)
455					}
456				}
457	
458				s, err := Open(dir)
459				if err == nil {
460					_ = s.Close()
461					t.Fatal("Open on unusable data must fail")
462				}
463				if s != nil {
464					t.Fatalf("failed Open must return nil handle, got %#v", s)
465				}
466				if errors.Is(err, ErrClosed) {
467					t.Fatalf("data error must not be masked as ErrClosed: %v", err)
468				}
469	
470				// 失败的 Open 不得把目录一直占住：另一次打开仍会到达数据校验
471				// 阶段并因同样的数据问题失败，而不是返回“目录正在使用”。
472				if _, err2 := Open(dir); err2 == nil {
473					t.Fatal("second Open must still fail on the bad data")
474				} else if strings.Contains(err2.Error(), alreadyInUseMsg) {
475					t.Fatalf("failed Open left the directory locked: %v", err2)
476				}
477	
478				// 调用方修正数据问题后再次打开应成功。
479				if err := os.RemoveAll(filepath.Join(dir, dataName)); err != nil {
480					t.Fatal(err)
481				}
482				s2, err := Open(dir)
483				if err != nil {
484					t.Fatalf("reopen after fixing data: %v", err)
485				}
486				if p, err := s2.RegisterPatient(doc, "修复后患者"); err != nil {
487					t.Fatalf("store unusable after fixing data: %v", err)
488				} else if _, err := s2.GetPatient(doc, p.ID); err != nil {
489					t.Fatalf("fixed store cannot read back: %v", err)
490				}
491				if err := s2.Close(); err != nil {
492					t.Fatal(err)
493				}
494			})
495		}
496	}
