498	// ---- 关闭与接手交错：旧 Store 余下的关闭动作不能破坏新 Store 的独占 ----
499	
500	func TestCloseOpenInterleavingKeepsExclusivity(t *testing.T) {
501		dir := t.TempDir()
502		s1, err := Open(dir)
503		if err != nil {
504			t.Fatal(err)
505		}
506		p, err := s1.RegisterPatient(doc, "交接患者")
507		if err != nil {
508			t.Fatal(err)
509		}
510	
511		// 还原关闭与接手的最坏交错：s1 的 Close 先释放文件锁（尚未走完全部
512		// 关闭动作），此刻 s2 合法接手同一目录；随后 s1 才完成余下的关闭动作。
513		// s1 余下的动作（关闭句柄、清理锁标记）绝不能打断 s2 的独占。
514		unlockFile(s1.lock)
515		s2, err := Open(dir)
516		if err != nil {
517			t.Fatalf("takeover during predecessor close must succeed: %v", err)
518		}
519		t.Cleanup(func() { _ = s2.Close() })
520		if err := s1.Close(); err != nil {
521			t.Fatalf("predecessor finishing close: %v", err)
522		}
523	
524		// s2 占用期间，任何第三个调用方（本进程内）都必须立即被拒绝。
525		s3, err := Open(dir)
526		if err == nil {
527			_ = s3.Close()
528			t.Fatal("third Open must be rejected while successor holds the directory")
529		}
530		if s3 != nil {
531			t.Fatalf("rejected Open must return nil handle, got %#v", s3)
532		}
533		if !strings.Contains(err.Error(), alreadyInUseMsg) {
534			t.Fatalf("error does not say directory is in use: %v", err)
535		}
536	
537		// 旧 Store 保持已关闭语义，不因交接复活；再次关闭也不影响新 Store。
538		if _, err := s1.RegisterPatient(doc, "旧句柄患者"); !errors.Is(err, ErrClosed) {
539			t.Fatalf("old handle method err = %v, want ErrClosed", err)
540		}
541		if err := s1.Close(); !errors.Is(err, ErrClosed) {
542			t.Fatalf("old handle second Close err = %v, want ErrClosed", err)
543		}
544	
545		// 新 Store 读到接手前已提交的数据，并能继续正常保存。
546		if got, err := s2.GetPatient(doc, p.ID); err != nil || got.Name != "交接患者" {
547			t.Fatalf("successor cannot read committed data: %+v, %v", got, err)
548		}
549		if _, err := s2.RegisterPatient(doc, "接手后患者"); err != nil {
550			t.Fatalf("successor cannot save after interleaved close: %v", err)
551		}
552	
553		// 新 Store 正常关闭后目录释放，之后可再次打开。
554		if err := s2.Close(); err != nil {
555			t.Fatal(err)
556		}
557		s4, err := Open(dir)
558		if err != nil {
559			t.Fatalf("reopen after successor close: %v", err)
560		}
561		t.Cleanup(func() { _ = s4.Close() })
562		if got, err := s4.GetPatient(doc, p.ID); err != nil || got.Name != "交接患者" {
563			t.Fatalf("data lost across handoff: %+v, %v", got, err)
564		}
565	}
566	
567	// ---- 关闭后的旧句柄不因新 Store 打开同一目录而复活 ----
568	
569	func TestClosedHandleStaysClosedAfterReopen(t *testing.T) {
570		dir := t.TempDir()
571		s1, err := Open(dir)
